// @Service: semantic — marks this as business logic. No extra behavior over @Component.
// But the team immediately knows this is the business layer, not data access or web.
package com.bank.mutualfund.service;

import com.bank.mutualfund.dto.NavResponse;
import com.bank.mutualfund.model.*;
import com.bank.mutualfund.repository.FundRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDateTime;

@Service  // semantic — "this is business logic"
@RequiredArgsConstructor
@Slf4j
public class NavCalculationService {

    private final FundRepository fundRepo;  // @Repository — exception translation active

    @Transactional
    public NavResponse calculateNav(String fundId) {
        log.info("Calculating NAV for fund {}", fundId);

        MutualFund fund = fundRepo.findById(fundId)
            .orElseThrow(() -> new IllegalArgumentException("Fund not found: " + fundId));

        var holdings = fundRepo.findHoldingsByFundId(fundId);

        // Calculate total market value of all holdings
        BigDecimal totalMarketValue = holdings.stream()
            .map(FundHolding::getMarketValue)
            .reduce(BigDecimal.ZERO, BigDecimal::add);

        // NAV = Total AUM / Total Units
        BigDecimal previousNav = fund.getNav();
        BigDecimal newNav = totalMarketValue.divide(fund.getUnitsTotal(), 4, RoundingMode.HALF_UP);
        BigDecimal changePercent = newNav.subtract(previousNav)
            .divide(previousNav, 4, RoundingMode.HALF_UP)
            .multiply(new BigDecimal("100"));

        fund.updateNav(newNav);
        fundRepo.save(fund);

        log.info("NAV updated: {} → {} ({}%)", previousNav, newNav, changePercent);

        var holdingDetails = holdings.stream()
            .map(h -> new NavResponse.HoldingDetail(
                h.getSymbol(), h.getQuantity(), h.getCurrentPrice(), h.getMarketValue()))
            .toList();

        return new NavResponse(fundId, fund.getFundName(), previousNav, newNav,
            changePercent, totalMarketValue, LocalDateTime.now(), holdingDetails);
    }
}
