@RequiredArgsConstructor
public class NavController {

    private final NavCalculationService navService; // injected by Spring — NOT new!

    @GetMapping("/{fundId}/nav")
    public NavResponse calculateNav(@PathVariable String fundId) {
        return navService.calculateNav(fundId);
    }

    // BAD — creating with new bypasses @Transactional, @PostConstruct, everything:
    // NavCalculationService bad = new NavCalculationService(repo); // NO proxy! NO transaction!
}
